window.MAO_POEMS = [{"t": "贺新郎·别友", "d": "一九二三年", "c": "挥手从兹去。更那堪凄然相向，苦情重诉。眼角眉梢都似恨，热泪欲零还住。知误会前番书语。过眼滔滔云共雾，算人间知己吾和汝。人有病，天知否？\n今朝霜重东门路，照横塘半天残月，凄清如许。汽笛一声肠已断，从此天涯孤旅。凭割断愁丝恨缕。要似昆仑崩绝壁，又恰像台风扫寰宇。重比翼，和云翥。", "b": "1923年，毛泽东因革命工作需要即将离湘，在长沙与妻子杨开慧话别。词以夫妻离情起笔，写革命者以天下为己任的胸怀。", "a": "上阕叙离愁与误会，情致婉转；过片「今朝霜重东门路」转写送别实景。结以「昆仑崩绝壁」「台风扫寰宇」喻革命风暴，将儿女情长升华为改造世界的壮志，「重比翼，和云翥」寄望夫妻并肩投身革命。"}, {"t": "沁园春·长沙", "d": "一九二五年", "c": "独立寒秋，湘江北去，橘子洲头。看万山红遍，层林尽染；漫江碧透，百舸争流。鹰击长空，鱼翔浅底，万类霜天竞自由。怅寥廓，问苍茫大地，谁主沉浮？\n携来百侣曾游，忆往昔峥嵘岁月稠。恰同学少年，风华正茂；书生意气，挥斥方遒。指点江山，激扬文字，粪土当年万户侯。曾记否，到中流击水，浪遏飞舟？", "b": "1925年秋，毛泽东重游长沙橘子洲，面对湘江壮丽秋色，追忆早年求学与革命岁月，写下这首气势磅礴的词。", "a": "上阕写景，「万山红遍」「百舸争流」开阔雄浑；「问苍茫大地，谁主沉浮」陡然振起。下阕忆同窗「指点江山，激扬文字」，以「中流击水」明报国壮志。景、史、情交融，尽显青年革命者的自信与担当。"}, {"t": "菩萨蛮·黄鹤楼", "d": "一九二七年春", "c": "茫茫九派流中国，沉沉一线穿南北。烟雨莽苍苍，龟蛇锁大江。\n黄鹤知何去？剩有游人处。把酒酹滔滔，心潮逐浪高！", "b": "1927年春，大革命危急，毛泽东登武汉黄鹤楼，俯瞰长江，感慨革命前途未卜、同志壮志难伸。", "a": "「茫茫九派」「沉沉一线」以空间之广写形势之重；「龟蛇锁大江」暗喻时局艰危。后阕「把酒酹滔滔，心潮逐浪高」于低抑中迸发坚定信念，苍茫沉郁中见革命者不息的豪情。"}, {"t": "西江月·秋收起义", "d": "一九二七年秋", "c": "军叫工农革命，旗号镰刀斧头。匡庐一带不停留，要向潇湘直进。\n地主重重压迫，农民个个同仇。秋收时节暮云愁，霹雳一声暴动。", "b": "1927年秋，毛泽东领导湘赣边界秋收起义，这首小令纪实般写下起义队伍的旗帜、口号与进军方向。", "a": "上阕「军叫工农革命，旗号镰刀斧头」直白如口号，尽显工农武装的崭新面貌；「要向潇湘直进」写出进军气势。下阕「秋收时节暮云愁，霹雳一声暴动」以雷霆喻起义，朴素刚健，是武装斗争的嘹亮序曲。"}, {"t": "西江月·井冈山", "d": "一九二八年秋", "c": "山下旌旗在望，山头鼓角相闻。敌军围困万千重，我自岿然不动。\n早已森严壁垒，更加众志成城。黄洋界上炮声隆，报道敌军宵遁。", "b": "1928年秋，黄洋界保卫战击退来犯之敌，毛泽东喜闻捷报，写此词赞井冈山军民的顽强斗志。", "a": "「敌军围困万千重，我自岿然不动」以对比显从容定力；「早已森严壁垒，更加众志成城」点出人民战争的法宝。结句「黄洋界上炮声隆，报道敌军宵遁」于轻快中见胜券在握，豪迈洗练。"}, {"t": "清平乐·蒋桂战争", "d": "一九二九年秋", "c": "风云突变，军阀重开战。洒向人间都是怨，一枕黄粱再现。\n红旗跃过汀江，直下龙岩上杭。收拾金瓯一片，分田分地真忙。", "b": "1929年秋，蒋介石与桂系军阀混战，红军乘机在闽西开辟根据地，词写军阀混战与革命根据地发展的对照。", "a": "上阕「风云突变，军阀重开战」一笔揭穿统治阶级内斗；「一枕黄粱」讽其图谋虚妄。下阕「红旗跃过汀江」「分田分地真忙」写根据地欣欣向荣，以反动混战反衬土地革命的生机，冷峻而乐观。"}, {"t": "采桑子·重阳", "d": "一九二九年十月", "c": "人生易老天难老，岁岁重阳。今又重阳，战地黄花分外香。\n一年一度秋风劲，不似春光。胜似春光，寥廓江天万里霜。", "b": "1929年重阳，毛泽东身处逆境却雄姿不减，借秋菊抒发革命者旷达乐观的情怀。", "a": "「人生易老天难老」起笔哲理深沉；「战地黄花分外香」以硝烟中的菊花写革命豪情。下阕「不似春光」「胜似春光」翻案传统悲秋，以「寥廓江天万里霜」收束，境界开阔，昂扬向上。"}, {"t": "如梦令·元旦", "d": "一九三〇年一月", "c": "宁化、清流、归化，路隘林深苔滑。今日向何方，直指武夷山下。山下山下，风展红旗如画。", "b": "1930年元旦，红军转战闽西，词写行军途中的艰险与红旗招展的明快画面。", "a": "「路隘林深苔滑」以三字短语写行军之难；「直指武夷山下」显目标明确。叠句「山下山下，风展红旗如画」于险境中突现明朗壮美的意境，短小精悍，举重若轻。"}, {"t": "减字木兰花·广昌路上", "d": "一九三〇年二月", "c": "漫天皆白，雪里行军情更迫。头上高山，风卷红旗过大关。\n此行何去？赣江风雪迷漫处。命令昨颁，十万工农下吉安。", "b": "1930年2月，红军由广昌向赣江挺进，词写雪中行军的紧迫与必胜信念。", "a": "「漫天皆白，雪里行军情更迫」以雪景衬军情；「风卷红旗过大关」动态如画。问答「此行何去？赣江风雪迷漫处」领起，结以「十万工农下吉安」，于肃杀中见雷霆万钧之势。"}, {"t": "蝶恋花·从汀州向长沙", "d": "一九三〇年七月", "c": "六月天兵征腐恶，万丈长缨要把鲲鹏缚。赣水那边红一角，偏师借重黄公略。\n百万工农齐踊跃，席卷江西直捣湘和鄂。国际悲歌歌一曲，狂飙为我从天落。", "b": "1930年7月，红军自汀州进军长沙，词写「百万工农」席卷江西、直捣湘鄂的浩大声势。", "a": "上阕「万丈长缨要把鲲鹏缚」以神话喻缚敌雄心；下阕「席卷江西直捣湘和鄂」写工农踊跃。结以「狂飙为我从天落」状革命风暴之不可抗拒，气吞山河，是早期武装斗争的恢弘画卷。"}, {"t": "渔家傲·反第一次大“围剿”", "d": "一九三一年春", "c": "万木霜天红烂漫，天兵怒气冲霄汉。雾满龙冈千嶂暗，齐声唤，前头捉了张辉瓒。\n二十万军重入赣，风烟滚滚来天半。唤起工农千百万，同心干，不周山下红旗乱。", "b": "1931年春，红军在龙冈伏击，活捉敌将张辉瓒，粉碎国民党第一次「围剿」，词纪此捷。", "a": "「万木霜天红烂漫」以景衬战云；「齐声唤，前头捉了张辉瓒」口语入词，生动可喜。下阕「唤起工农千百万」点人民战争伟力，「不周山下红旗乱」化用共工神话，写革命翻天覆地的气势。"}, {"t": "渔家傲·反第二次大“围剿”", "d": "一九三一年夏", "c": "白云山头云欲立，白云山下呼声急，枯木朽株齐努力。枪林逼，飞将军自重霄入。\n七百里驱十五日，赣水苍茫闽山碧，横扫千军如卷席。有人泣，为营步步嗟何及！", "b": "1931年夏，红军十五天内横扫七百里，粉碎第二次「围剿」，词写运动战的凌厉与敌军溃败。", "a": "「白云山头云欲立」以云拟人，气氛紧张；「枪林逼，飞将军自重霄入」赞红军神速。下阕「横扫千军如卷席」写摧枯拉朽，「有人泣，为营步步嗟何及」讽蒋军战术失败，对比鲜明，酣畅淋漓。"}, {"t": "菩萨蛮·大柏地", "d": "一九三三年夏", "c": "赤橙黄绿青蓝紫，谁持彩练当空舞？雨后复斜阳，关山阵阵苍。\n当年鏖战急，弹洞前村壁。装点此关山，今朝更好看。", "b": "1933年夏，毛泽东重过大柏地，忆四年前红军在此激战，弹痕犹在，触景生情。", "a": "「赤橙黄绿青蓝紫，谁持彩练当空舞」以彩虹起兴，色彩斑斓；「当年鏖战急，弹洞前村壁」由景入史。结以「装点此关山，今朝更好看」，将战争创伤化为壮丽风景，举重若轻，意味深长。"}, {"t": "清平乐·会昌", "d": "一九三四年夏", "c": "东方欲晓，莫道君行早。踏遍青山人未老，风景这边独好。\n会昌城外高峰，颠连直接东溟。战士指看南粤，更加郁郁葱葱。", "b": "1934年夏，红军第五次反「围剿」失利在即，毛泽东登上会昌山，于忧思中仍见必胜信念。", "a": "「东方欲晓，莫道君行早」以晨景起笔，含勤勉自勉；「踏遍青山人未老，风景这边独好」于困顿中显豁达。下阕「更加郁郁葱葱」写南方远景，于低回处藏昂扬，是逆境中的乐观之歌。"}, {"t": "十六字令三首", "d": "一九三四年至一九三五年", "c": "山，快马加鞭未下鞍。惊回首，离天三尺三。\n山，倒海翻江卷巨澜。奔腾急，万马战犹酣。\n山，刺破青天锷未残。天欲堕，赖以拄其间。", "b": "1934—1935年长征途中，毛泽东连续以三首十六字小令咏山，写红军翻山越岭的雄姿。", "a": "三首皆以「山」起，分别以「离天三尺三」「万马战犹酣」「赖以拄其间」状山之高、之势、之固。以山喻红军，尺幅千里，刚健奇崛，于极短篇幅中见长征的磅礴气魄。"}, {"t": "忆秦娥·娄山关", "d": "一九三五年二月", "c": "西风烈，长空雁叫霜晨月。霜晨月，马蹄声碎，喇叭声咽。\n雄关漫道真如铁，而今迈步从头越。从头越，苍山如海，残阳如血。", "b": "1935年2月，红军二渡赤水、重占娄山关，词写拂晓激战后的苍凉与再起步的坚毅。", "a": "上阕「西风烈」「霜晨月」以冷色写征战之严；「马蹄声碎，喇叭声咽」声情凄清。下阕「雄关漫道真如铁，而今迈步从头越」于悲壮中转豪迈，「苍山如海，残阳如血」以壮阔收束，沉郁顿挫，撼人心魄。"}, {"t": "七律·长征", "d": "一九三五年十月", "c": "红军不怕远征难，万水千山只等闲。\n五岭逶迤腾细浪，乌蒙磅礴走泥丸。\n金沙水拍云崖暖，大渡桥横铁索寒。\n更喜岷山千里雪，三军过后尽开颜。", "b": "1935年10月红军长征胜利在望，毛泽东以七律概括二万五千里征途的千难万险与英雄气概。", "a": "首联「万水千山只等闲」定下豪迈基调；颔联以「腾细浪」「走泥丸」缩千山于股掌；颈联「云崖暖」「铁索寒」写金沙大渡之险。尾联「更喜岷山千里雪，三军过后尽开颜」以胜利欢颜收束，气势恢宏，是长征的史诗。"}, {"t": "念奴娇·昆仑", "d": "一九三五年十月", "c": "横空出世，莽昆仑，阅尽人间春色。飞起玉龙三百万，搅得周天寒彻。夏日消溶，江河横溢，人或为鱼鳖。千秋功罪，谁人曾与评说？\n而今我谓昆仑：不要这高，不要这多雪。安得倚天抽宝剑，把汝裁为三截？一截遗欧，一截赠美，一截还东国。太平世界，环球同此凉热。", "b": "1935年10月，长征将抵陕北，毛泽东望昆仑雪山，驰骋想象，抒发改造山河、世界和平的宏愿。", "a": "上阕写昆仑「阅尽人间春色」而又「江河横溢」的功罪两面；下阕「不要这高，不要这多雪」「裁为三截」以奇想遣山。结以「太平世界，环球同此凉热」由个人豪情升华为人类大同理想，气象高大。"}, {"t": "清平乐·六盘山", "d": "一九三五年十月", "c": "天高云淡，望断南飞雁。不到长城非好汉，屈指行程二万。\n六盘山上高峰，红旗漫卷西风。今日长缨在手，何时缚住苍龙？", "b": "1935年10月，红军翻越长征最后一座大山六盘山，毛泽东临风寄慨，望长征将竟。", "a": "「天高云淡，望断南飞雁」以秋空起兴，含对南方苏区与战友的遥念；「不到长城非好汉」警策豪迈。下阕「红旗漫卷西风」「何时缚住苍龙」写胜利在望、敌忾未消，俊爽刚健。"}, {"t": "沁园春·雪", "d": "一九三六年二月", "c": "北国风光，千里冰封，万里雪飘。望长城内外，惟余莽莽；大河上下，顿失滔滔。山舞银蛇，原驰蜡象，欲与天公试比高。须晴日，看红装素裹，分外妖娆。\n江山如此多娇，引无数英雄竞折腰。惜秦皇汉武，略输文采；唐宗宋祖，稍逊风骚。一代天骄，成吉思汗，只识弯弓射大雕。俱往矣，数风流人物，还看今朝。", "b": "1936年2月，毛泽东率军渡河东征，途中所作。1945年重庆谈判时书赠柳亚子，传诵一时。", "a": "上阕写北国雪景，「千里冰封」「欲与天公试比高」雄视古今；下阕评说秦皇汉武等英雄，「数风流人物，还看今朝」翻历史案。景、史、论交融，气魄横绝，是毛泽东诗词的代表作。"}, {"t": "七律·人民解放军占领南京", "d": "一九四九年四月", "c": "钟山风雨起苍黄，百万雄师过大江。\n虎踞龙盘今胜昔，天翻地覆慨而慷。\n宜将剩勇追穷寇，不可沽名学霸王。\n天若有情天亦老，人间正道是沧桑。", "b": "1949年4月23日解放军横渡长江解放南京，毛泽东闻讯赋诗，宣告蒋家王朝覆灭。", "a": "首联「钟山风雨起苍黄」写巨变之速；颔联「宜将剩勇追穷寇」主张乘胜进军。颈联「天若有情天亦老」化用李贺，尾联「人间正道是沧桑」以哲理收束，雄辩地阐明革命必须进行到底。"}, {"t": "七律·和柳亚子先生", "d": "一九四九年四月二十九日", "c": "饮茶粤海未能忘，索句渝州叶正黄。\n三十一年还旧国，落花时节读华章。\n牢骚太盛防肠断，风物长宜放眼量。\n莫道昆明池水浅，观鱼胜过富春江。", "b": "1949年4月，柳亚子赋诗感叹南归，毛泽东步韵相和，劝其放宽心、共建设新中国。", "a": "「牢骚太盛防肠断，风物长宜放眼量」以箴言劝友；「莫道昆明池水浅，观鱼胜过富春江」喻北京可施展抱负。全诗于唱和中见领袖襟怀与对民主人士的恳切相待。"}, {"t": "浣溪沙·和柳亚子先生", "d": "一九五〇年十月", "c": "长夜难明赤县天，百年魔怪舞翩跹，人民五亿不团圆。\n一唱雄鸡天下白，万方乐奏有于阗，诗人兴会更无前。", "b": "1950年国庆，柳亚子填词颂盛世，毛泽东依韵和作，写各族人民欢庆新生的图景。", "a": "「长夜难明赤县天」回顾百年苦难；「百年魔怪舞翩跹」写旧世乱象。下阕「一唱雄鸡天下白」「万方乐奏有于阗」以明朗意象写新中国分立冬去春来，欢快明朗，气象一新。"}, {"t": "浪淘沙·北戴河", "d": "一九五四年夏", "c": "大雨落幽燕，白浪滔天，秦皇岛外打鱼船。一片汪洋都不见，知向谁边？\n往事越千年，魏武挥鞭，东临碣石有遗篇。萧瑟秋风今又是，换了人间。", "b": "1954年夏，毛泽东于北戴河观沧海，抚今追昔，思曹操观海之事，写建设年代的心胸。", "a": "「大雨落幽燕，白浪沧海」以壮阔海景开篇；「往事越千年，魏武挥鞭」怀古。结以「萧瑟秋风今又是，换了人间」对比古今，于雄浑中见时代巨变之慨，豪迈深沉。"}, {"t": "水调歌头·游泳", "d": "一九五六年六月", "c": "才饮长沙水，又食武昌鱼。万里长江横渡，极目楚天舒。不管风吹浪打，胜似闲庭信步，今日得宽馀。子在川上曰：逝者如斯夫！\n风樯动，龟蛇静，起宏图。一桥飞架南北，天堑变通途。更立西江石壁，截断巫山云雨，高峡出平湖。神女应无恙，当惊世界殊。", "b": "1956年6月，毛泽东横渡长江，写下这首词，既写搏浪之乐，也写武汉长江大桥与三峡宏图。", "a": "上阕「万里长江横渡」写畅游豪情；「不管风吹浪打，胜似闲庭信步」见从容。下阕「更立西江石壁」「高峡出平湖」畅想水利伟业，「神女应无恙，当惊世界殊」以浪漫收束，现实与理想辉映。"}, {"t": "蝶恋花·答李淑一", "d": "一九五七年五月十一日", "c": "我失骄杨君失柳，杨柳轻飏直上重霄九。问讯吴刚何所有，吴刚捧出桂花酒。\n寂寞嫦娥舒广袖，万里长空且为忠魂舞。忽报人间曾伏虎，泪飞顿作倾盆雨。", "b": "1957年，李淑一函寄悼亡词，毛泽东以这首蝶恋花相答，悼念亡妻杨开慧与战友柳直荀。", "a": "「我失骄杨君失柳」以「骄杨」赞烈士；「杨柳轻飏直上重霄九」化入仙境。下阕吴刚捧桂、嫦娥舒袖，以神话写英烈受敬，「泪飞顿作倾盆雨」写忠魂之悲喜，深情浪漫，感人至深。"}, {"t": "七律二首·送瘟神", "d": "一九五八年七月一日", "c": "读六月三十日人民日报，余江县消灭了血吸虫。浮想联翩，夜不能寐。微风拂煦，旭日临窗。遥望南天，欣然命笔。\n【其一】\n绿水青山枉自多，华佗无奈小虫何！\n千村薜荔人遗矢，万户萧疏鬼唱歌。\n坐地日行八万里，巡天遥看一千河。\n牛郎欲问瘟神事，一样悲欢逐逝波。\n【其二】\n春风杨柳万千条，六亿神州尽舜尧。\n红雨随心翻作浪，青山着意化为桥。\n天连五岭银锄落，地动三河铁臂摇。\n借问瘟君欲何往，纸船明烛照天烧。", "b": "1958年，毛泽东读余江县消灭血吸虫喜报，浮想联翩，作二律纪新社会除害兴利的奇迹。", "a": "其一「绿水青山枉自多」痛陈旧世瘟神横行；「千村薜荔人遗矢」写民生凋敝。其二「春风杨柳万千条」转写新天，「六亿神州尽舜尧」颂人民伟力，「纸船明烛照天烧」送走瘟神，今昔对照，激情奔涌。"}, {"t": "七律·到韶山", "d": "一九五九年六月", "c": "一九五九年六月二十五日到韶山。离别这个地方已有三十二周年了。\n别梦依稀咒逝川，故园三十二年前。\n红旗卷起农奴戟，黑手高悬霸主鞭。\n为有牺牲多壮志，敢教日月换新天。\n喜看稻菽千重浪，遍地英雄下夕烟。", "b": "1959年6月，毛泽东阔别三十二年的故乡韶山，见巨变而忆牺牲的亲友，感慨万端。", "a": "「别梦依稀咒逝川」起笔沉郁；「红旗卷起农奴戟」忆革命烽火。颈联「为有牺牲多壮志，敢教日月换新天」为名句，颂牺牲换来的天地翻覆。尾联写稻浪丰收，于悲壮中见欣慰。"}, {"t": "七律·登庐山", "d": "一九五九年七月一日", "c": "一山飞峙大江边，跃上葱茏四百旋。\n冷眼向洋看世界，热风吹雨洒江天。\n云横九派浮黄鹤，浪下三吴起白烟。\n陶令不知何处去，桃花源里可耕田？", "b": "1959年7月，毛泽东登庐山，写登高所见与对时局、建设的热望。", "a": "「一山飞峙大江边」写庐山雄姿；「冷眼向洋看世界」显从容自信。下阕「陶令不知何处去，桃花源里可耕田」借陶渊明讽逃避现实，暗喻脚踏实地搞建设，景中寓理，洒脱明快。"}, {"t": "七绝·为女民兵题照", "d": "一九六一年二月", "c": "飒爽英姿五尺枪，曙光初照演兵场。\n中华儿女多奇志，不爱红装爱武装。", "b": "1961年2月，毛泽东为一张女民兵持枪照片题诗，赞颂全民皆兵、巾帼不让须眉。", "a": "「飒爽英姿五尺枪，曙光初照演兵场」勾勒女民兵英姿；「中华儿女多奇志，不爱红装爱武装」以对比颂其志向，语言明快，是那个年代民兵风采的传神写照。"}, {"t": "七绝·为李进同志题所摄庐山仙人洞照", "d": "一九六一年九月九日", "c": "暮色苍茫看劲松，乱云飞渡仍从容。\n天生一个仙人洞，无限风光在险峰。", "b": "1961年9月，毛泽东为江青所摄庐山仙人洞照片题诗，于困难时期寄寓坚韧自信。", "a": "「暮色苍茫看劲松，乱云飞渡仍从容」以劲松喻定力；「天生一个仙人洞，无限风光在险峰」由景及理，言险峰方见佳境，于逆境中见乐观与定力，含蓄而有力。"}, {"t": "七律·答友人", "d": "一九六一年", "c": "九嶷山上白云飞，帝子乘风下翠微。\n斑竹一枝千滴泪，红霞万朵百重衣。\n洞庭波涌连天雪，长岛人歌动地诗。\n我欲因之梦寥廓，芙蓉国里尽朝晖。", "b": "1961年，友人自湖南来函，毛泽东以诗相答，借湖湘神话写故乡与时代的新貌。", "a": "「九嶷山上白云飞」以娥皇女英神话起笔；「芙蓉国里尽朝晖」写湖南新景。下阕「洞庭波涌连天雪，长岛人歌动地诗」壮阔热烈，「我欲因之梦寥廓」由实入虚，浪漫瑰丽。"}, {"t": "七律·和郭沫若同志", "d": "一九六一年十一月十七日", "c": "一从大地起风雷，便有精生白骨堆。\n僧是愚氓犹可训，妖为鬼蜮必成灾。\n金猴奋起千钧棒，玉宇澄清万里埃。\n今日欢呼孙大圣，只缘妖雾又重来。", "b": "1961年，郭沫若咏孙悟空诗，毛泽东步韵相和，借西游记故事谈对敌斗争策略。", "a": "「一从大地起风雷」写革命风暴起；「金猴奋起千钧棒，玉宇澄清万里埃」以孙悟空喻驱邪。结以「今日欢呼孙大圣，只缘妖雾又重来」借神话警喻现实中仍需斗争，风趣而犀利。"}, {"t": "卜算子·咏梅", "d": "一九六一年十二月", "c": "读陆游咏梅词，反其意而用之。\n风雨送春归，飞雪迎春到。已是悬崖百丈冰，犹有花枝俏。\n俏也不争春，只把春来报。待到山花烂漫时，她在丛中笑。", "b": "1961年冬，毛泽东读陆游咏梅词反其意而用之，借梅花写共产党人不畏严寒、无私奉献的品格。", "a": "「已是悬崖百丈冰，犹有花枝俏」写梅之傲雪；「俏也不争春，只把春来报」翻陆游孤芳自赏之旨，以「待到山花烂漫时，她在丛中笑」写功成不居，境界高远，是咏物言志的典范。"}, {"t": "七律·冬云", "d": "一九六二年十二月二十六日", "c": "雪压冬云白絮飞，万花纷谢一时稀。\n高天滚滚寒流急，大地微微暖气吹。\n独有英雄驱虎豹，更无豪杰怕熊罴。\n梅花欢喜漫天雪，冻死苍蝇未足奇。", "b": "1962年12月26日毛泽东生日，时值国际局势紧张，以冬云喻环境，写傲寒斗雪的意志。", "a": "「雪压冬云白絮飞」写寒云压顶；「独有英雄驱虎豹，更无豪杰怕熊罴」以对比显胆魄。下阕「梅花欢喜漫天雪，冻死苍蝇未足奇」以梅蝇喻敌我，于严冬中见斗争豪情，刚健冷峻。"}, {"t": "满江红·和郭沫若同志", "d": "一九六三年一月九日", "c": "小小寰球，有几个苍蝇碰壁。嗡嗡叫，几声凄厉，几声抽泣。蚂蚁缘槐夸大国，蚍蜉撼树谈何易。正西风落叶下长安，飞鸣镝。\n多少事，从来急；天地转，光阴迫。一万年太久，只争朝夕。四海翻腾云水怒，五洲震荡风雷激。要扫除一切害人虫，全无敌。", "b": "1963年1月，毛泽东和郭沫若《满江红》，纵论天下大势，抒发反帝反霸的坚强决心。", "a": "上阕「小小寰球，有几个苍蝇碰壁」以嘲讽起；「蚂蚁缘槐夸大国」讽霸权虚妄。下阕「四海翻腾云水怒，五洲震荡风雷激」写世界革命浪潮，「要扫除一切害人虫」气势磅礴，是放眼全球的战斗宣言。"}, {"t": "七律·吊罗荣桓同志", "d": "一九六三年十二月", "c": "记得当年草上飞，红军队里每相违。\n长征不是难堪日，战锦方为大问题。\n斥鷃每闻欺大鸟，昆鸡长笑老鹰非。\n君今不幸离人世，国有疑难可问谁？", "b": "1963年12月罗荣桓元帅逝世，毛泽东赋诗悼念，赞其政治品格与战友深情。", "a": "「记得当年草上飞」忆战争岁月；「红军队里每相违」写聚少离多。颈联「长征不是难堪日，战锦方为大问题」评其功过担当，结以「国有疑难可问谁」痛失栋梁，沉痛深切，朴挚感人。"}, {"t": "贺新郎·读史", "d": "一九六四年春", "c": "人猿相揖别。只几个石头磨过，小儿时节。铜铁炉中翻火焰，为问何时猜得？不过几千寒热。人世难逢开口笑，上疆场彼此弯弓月。流遍了，郊原血。\n一篇读罢头飞雪，但记得斑斑点点，几行陈迹。五帝三皇神圣事，骗了无涯过客。有多少风流人物？盗跖庄蹻流誉后，更陈王奋起挥黄钺。歌未竟，东方白。", "b": "1964年春，毛泽东读二十四史有所感，以词纵论数千年阶级争斗，翻封建正统史观。", "a": "「人猿相揖别」起笔写人类进化；「盗跖庄蹻流誉后，更陈王奋起挥黄钺」推重农民起义。下阕「五帝三皇神圣事，骗了无涯过客」破帝王神话，「歌未竟，东方白」由古及今，气势磅礴，史识独到。"}, {"t": "水调歌头·重上井冈山", "d": "一九六五年五月", "c": "久有凌云志，重上井冈山。千里来寻故地，旧貌变新颜。到处莺歌燕舞，更有潺潺流水，高路入云端。过了黄洋界，险处不须看。\n风雷动，旌旗奋，是人寰。三十八年过去，弹指一挥间。可上九天揽月，可下五洋捉鳖，谈笑凯歌还。世上无难事，只要肯登攀。", "b": "1965年5月，毛泽东重上井冈山，距1927年割据三十八年，抚今追昔，写斗争结晶与继续革命之志。", "a": "「久有凌云志，重上井冈山」起笔明志；「到处莺歌燕舞」写旧地新颜。下阕「可上九天揽月，可下五洋捉鳖」豪气干云，「世上无难事，只要肯登攀」以警句收束，刚健昂扬。"}, {"t": "念奴娇·鸟儿问答", "d": "一九六五年秋", "c": "鲲鹏展翅，九万里，翻动扶摇羊角。背负青天朝下看，都是人间城郭。炮火连天，弹痕遍地，吓倒蓬间雀。怎么得了，哎呀我要飞跃。\n借问君去何方，雀儿答道：有仙山琼阁。不见前年秋月朗，订了三家条约。还有吃的，土豆烧熟了，再加牛肉。不须放屁，试看天地翻覆。", "b": "1965年秋，毛泽东以鲲鹏与蓬间雀对话的寓言词，讽刺当时国际共运中的妥协论调。", "a": "「鲲鹏展翅九万里」以壮鸟喻革命力量；「蓬间雀」怯懦窃语，问答之间寓立场之别。结以「土豆烧熟了，再加牛肉」戏拟「福利共产主义」口号，幽默犀利，于谈笑中见原则。"}, {"t": "七律·洪都", "d": "一九六五年十二月", "c": "到得洪都又一年，祖生击楫至今传。\n闻鸡久听南天雨，立马曾挥北地鞭。\n鬓雪飞来成废料，彩云长在有新天。\n年年后浪推前浪，江草江花处处鲜。", "b": "1965年12月，毛泽东至南昌（古洪都），怀王勃《滕王阁序》，写老区新貌与后继有人。", "a": "「到得洪都又一年」平起；「鬓雪飞来成废料」自谦年老。下阕「彩云长在有新天」望前景，「年年后浪推前浪」喻新人代起，结以「江草江花处处鲜」写生机，于平淡中见达观。"}, {"t": "七律·有所思", "d": "一九六六年六月", "c": "正是神都有事时，又来南国踏芳枝。\n青松怒向苍天发，败叶纷随碧水驰。\n一阵风雷惊世界，满街红绿走旌旗。\n凭阑静听潇潇雨，故国人民有所思。", "b": "1966年6月，毛泽东于风云变幻之际有所感怀，写对时局的忧思与对群众的瞩望。", "a": "「正是神都有事时」点明背景；「又来南国踏芳枝」写南行。下阕「青松怒向苍天发，败叶纷随碧水驰」以景物喻斗争双方，「一阵风雷惊世界」写变动将至，含蓄深沉，寄意遥深。"}];

